<?php
namespace Tests\Feature;use App\Domain\Profiles\Models\Profile;use App\Domain\Users\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class ProfileTest extends TestCase{use RefreshDatabase;public function test_profile_crud_and_audit():void{$u=User::factory()->create();Profile::create(['user_id'=>$u->id,'first_name'=>'Old','locale'=>'en']);Sanctum::actingAs($u);$this->getJson('/api/v1/profile')->assertOk();$this->putJson('/api/v1/profile',['first_name'=>'New','timezone'=>'Asia/Colombo'])->assertOk()->assertJsonPath('data.timezone','Asia/Colombo');$this->assertDatabaseHas('profiles',['user_id'=>$u->id,'first_name'=>'New']);$this->assertDatabaseHas('audit_logs',['event'=>'profile.updated']);$this->deleteJson('/api/v1/profile')->assertOk();$this->assertDatabaseMissing('profiles',['user_id'=>$u->id]);}}
